# Canary: compare error rate against baseline and decide automatically
def decide(base_err, canary_err, canary_reqs, min_reqs=500, max_ratio=1.5, slack=0.002):
    if canary_reqs < min_reqs:
        return "wait (only %d requests, need %d)" % (canary_reqs, min_reqs)
    if canary_err > base_err * max_ratio + slack:
        return "ROLLBACK"
    return "promote"

steps = [5, 25, 50, 100]  # traffic percent
# (baseline error, canary error, canary requests) observed at each step
obs = [(0.010, 0.011, 300), (0.010, 0.012, 2500), (0.010, 0.031, 5000)]
for pct, (b, c, n) in zip(steps, obs):
    d = decide(b, c, n)
    print("%3d%% traffic base=%.3f canary=%.3f n=%d -> %s" % (pct, b, c, n, d))
    if d == "ROLLBACK":
        print("traffic back to 0% canary")
        break

# Percentage rollout for a feature flag: stable hash puts each user in a bucket 0-99
import hashlib

def bucket(flag, user):
    h = hashlib.sha256((flag + ":" + user).encode()).hexdigest()
    return int(h, 16) % 100  # same user + flag always gives the same bucket

def enabled(flag, user, percent, staff=()):
    if user in staff:
        return True  # staff see it first
    return bucket(flag, user) < percent

users = ["u%d" % i for i in range(1000)]
for pct in (0, 10, 50, 100):
    on = sum(enabled("new-checkout", u, pct) for u in users)
    print("rollout %3d%% -> %d of 1000 users" % (pct, on))

# Raising 10% -> 50% keeps everyone who already had it
ten = {u for u in users if enabled("new-checkout", u, 10)}
fifty = {u for u in users if enabled("new-checkout", u, 50)}
print("10% group still on at 50%:", ten <= fifty)
